// The indicator database. Plain data, loaded by a script tag rather than
// fetched, so the page works from a file:// URL as well as over the web.
//
// An entry is a word or phrase you might meet in a clue, the types of wordplay
// it can signal, and a note on how it behaves. A word can belong to several
// types at once — "about" is an anagram indicator, a container and a reversal
// — which is half of what makes cryptics hard, so `types` is a list rather
// than a single label.
//
// To add one, add an object anywhere in the list: `word` lowercase, `types`
// drawn from the ids in TYPES below, and `notes` an empty string when there is
// nothing worth saying. It is hand-edited from here on — nothing regenerates
// it, so an edit will not be overwritten.
//
// A word listed twice is merged when the page loads: the types are pooled and
// both notes kept, so giving an existing word another type is just a matter of
// adding a second entry for it. The page reports every merge in the browser
// console, along with anything else that looks wrong — a capital letter, an
// unknown type, a slash or bracket, or an x or y standing in for the fodder,
// all of which would stop the word being found by typing it.
//
// Seeded from notes.md alongside it, seven word lists at crosswordunclued.com,
// twelve at cryptics.fandom.com and fourteen tables at clueclinic.com, merged
// so that a word listed in several places comes out as one entry carrying
// every type it was listed under.
//
// The types follow the categories at cryptics.fandom.com, which keeps letter
// selection whole and gives juxtaposition a category of its own, where
// crosswordunclued.com splits selection into acrostics and letter sequences
// and has nowhere to put juxtaposition at all. Its "substitution and movement"
// is `movement` here, holding both halves: a letter swapped for another, and a
// letter moved somewhere else in the word. `movement` is the shorter name for
// both. Neither is an anagram, which is a
// rearrangement of the same letters the solver has to find rather than a named
// change the clue spells out.
//
// Types with nothing to look up are left out: charades, double and cryptic
// definitions and &lit, which have no indicators at all, and linking words,
// which are the words left over once the wordplay is accounted for rather than
// a thing to search.

const TYPES = [
  {
    id: "anagram",
    label: "Anagram",
    reminder:
      "More of these than any other kind. Anything suggesting movement, damage or disorder. Count the letters: the fodder has to be exactly as long as the answer.",
  },
  {
    id: "homophone",
    label: "Homophone",
    reminder:
      "Say it out loud. Often applied to a substitution rather than to the answer itself.",
  },
  {
    id: "hidden",
    label: "Hidden",
    reminder:
      "The answer is sitting inside the clue's own words, usually spanning the gap between two of them.",
  },
  {
    id: "deletion",
    label: "Deletion",
    reminder:
      "Like selection, but says what to drop rather than what to keep. Also easily mistaken for an anagram indicator.",
  },
  {
    id: "selection",
    label: "Selection",
    reminder:
      "Take particular letters: firsts, lasts, middles, borders, every other one. Easily mistaken for an anagram indicator, so count the letters, and do not assume it starts from the first letter of the word after it.",
  },
  {
    id: "container",
    label: "Container",
    reminder:
      "One set of letters goes inside another. \"X about Y\" puts Y inside X; \"X in Y\" puts X inside Y.",
  },
  {
    id: "reversal",
    label: "Reversal",
    reminder:
      "Almost always used alongside another kind of wordplay. Up, rising and climbing only work in a down clue; back and west in an across clue.",
  },
  {
    id: "juxtaposition",
    label: "Juxtaposition",
    reminder:
      "The parts come out in the order they are written unless one of these says otherwise.",
  },
  {
    id: "palindrome",
    label: "Palindrome",
    reminder: "The answer reads the same both ways, so the clue only has to give you half of it.",
  },
  {
    id: "movement",
    label: "Movement",
    reminder:
      "A named change to one letter: swapped for another, or moved somewhere else in the word. Unlike an anagram the clue says exactly what to do, so there is nothing to discover — and unlike an anagram a substitution brings in a letter that was not there.",
  },
  {
    id: "abbreviation",
    label: "Abbreviation",
    reminder:
      "No indicator at all: a word that simply stands for letters. These are learnt rather than worked out.",
  },
];

